#!/usr/bin/env python3
"""
EQL Tracker 1.0.12 - self-extracting installer
---------------------------------------------------
Run this file (double-click on Windows, or:
    python EQL_Tracker_installer_v1.0.12.py)

It creates an "EQL Tracker" folder next to itself and unpacks the app into it,
then offers to launch. Nothing is installed system-wide and nothing is written
outside that folder - delete it and the app is gone.

Upgrading is the same file. Run it over an existing install and it replaces the
program files, but **every data folder is left exactly as it is**: your kill
history, lifetime stats, quests, character records and the item database are
never overwritten, never merged, never deleted.

This installer is ordinary readable Python with a zip carried inside it as
text. Nothing is downloaded and nothing is compiled - open it and check.
"""
import base64
import io
import os
import sys
import zipfile

VERSION = "1.0.12"
FOLDER = "EQL_Tracker"

# Any path inside one of these is DATA, not program. Existing files here are
# never replaced. Both are relative to the install folder.
#   Data/                       play data: kills, lifetime stats, quests,
#                               the reference *_db files, editable JSON
#   subprojects/eql_db/data/    the item database: icons, zone eras, effect
#                               pages, and the scraped corpus
DATA_DIRS = ("Data", "subprojects/eql_db/data")

PAYLOAD = ""


def is_data(rel):
    p = rel.replace("\\", "/")
    return any(p == d or p.startswith(d + "/") for d in DATA_DIRS)


def ask(prompt, default_yes=True):
    try:
        ans = input(prompt).strip().lower()
    except EOFError:                       # no console (rare); take the default
        return default_yes
    if not ans:
        return default_yes
    return ans in ("y", "yes")


def main():
    here = os.path.dirname(os.path.abspath(sys.argv[0])) or "."
    target = os.path.join(here, FOLDER)
    print("EQL Tracker %s installer" % VERSION)
    print("=" * 46)
    print("Installing to: %s" % target)

    z = zipfile.ZipFile(io.BytesIO(base64.b64decode(PAYLOAD)))
    names = [n for n in z.namelist() if not n.endswith("/")]

    # strip the archive's top folder so the layout lands directly in target
    top = names[0].split("/")[0] if names else ""
    if top and all(n.startswith(top + "/") for n in names):
        rels = [(n, n[len(top) + 1:]) for n in names]
    else:
        rels = [(n, n) for n in names]

    upgrading = os.path.isdir(target)
    program = [(a, r) for a, r in rels if not is_data(r)]
    data = [(a, r) for a, r in rels if is_data(r)]
    clobber = [r for a, r in program if os.path.exists(os.path.join(target, r))]

    if upgrading:
        print("\nAn existing install was found - this is an UPGRADE.")
        print("  %d program file(s) will be replaced." % len(clobber))
        print("  Data folders are left untouched:")
        for d in DATA_DIRS:
            full = os.path.join(target, d.replace("/", os.sep))
            n = sum(len(f) for _, _, f in os.walk(full)) if os.path.isdir(full) else 0
            print("      %-28s %s" % (d + "/", ("%d file(s) kept" % n) if n
                                      else "not present yet"))
        if not ask("\nProceed? [Y/n] "):
            print("Cancelled. Nothing was changed.")
            input("Press Enter to close.")
            return

    os.makedirs(target, exist_ok=True)
    written = kept = 0
    for arc, rel in rels:
        dest = os.path.join(target, rel.replace("/", os.sep))
        if is_data(rel) and os.path.exists(dest):
            kept += 1                      # never touch existing data
            continue
        os.makedirs(os.path.dirname(dest), exist_ok=True)
        with z.open(arc) as fsrc, open(dest, "wb") as fdst:
            fdst.write(fsrc.read())
        written += 1

    print("\nDone.")
    print("  %d file(s) written" % written)
    if kept:
        print("  %d existing data file(s) left as they were" % kept)
    print("  installed at %s" % target)

    print("\nYour data lives in:")
    for d in DATA_DIRS:
        print("  %s/" % os.path.join(target, d.replace("/", os.sep)))
    print("It is created on first run and preserved by every future upgrade.")

    # The app itself is stdlib-only. Only the item scraper needs anything.
    try:
        import requests  # noqa: F401
        import bs4       # noqa: F401
    except ImportError:
        print("\nOptional: the EQL DB scraper needs two packages.")
        print("  The tracker itself does NOT - it runs on the standard library.")
        print("  To enable scraping later:")
        print("      py -m pip install requests beautifulsoup4")

    app = os.path.join(target, "EQL_Tracker.pyw")
    if ask("\nLaunch EQL Tracker now? [Y/n] "):
        try:
            if sys.platform == "win32":
                os.startfile(app)          # noqa: S606
            else:
                import subprocess
                subprocess.Popen([sys.executable,
                                  os.path.join(target, "eql_tracker.py")])
            print("Launched. Happy hunting.")
        except Exception as e:
            print("Could not auto-launch (%r) - start it manually:" % e)
            print("  %s" % app)
    else:
        print("Start it any time by double-clicking:")
        print("  %s" % app)
    input("\nPress Enter to close.")


if __name__ == "__main__":
    main()
